import { test, expect } from '@playwright/test';

test.describe('Long-Running Task Persistence Across Page Refreshes', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/tasks');
  });

  test('should persist long-running task state across page refreshes', async ({ page }) => {
    // Setup: Intercept the API call to start a long-running task
    await page.route('**/api/tasks/start', (route) => {
      route.continue();
    });

    // Verify initial task state
    const taskList = page.getByRole('region', { name: /tasks/i });
    await expect(taskList).toBeVisible();

    // Verify task is listed
    const taskItem = page.getByRole('listitem', { name: /long-running task/i });
    await expect(taskItem).toBeVisible();

    // Verify task details are visible
    const taskName = page.getByText(/long-running task/i);
    await expect(taskName).toBeVisible();

    // Verify progress bar is visible
    const progressBar = page.getByRole('progressbar');
    await expect(progressBar).toBeVisible();

    // Verify task status is visible
    const taskStatus = page.getByText(/in progress/i);
    await expect(taskStatus).toBeVisible();

    // Verify refresh button is visible
    const refreshButton = page.getByRole('button', { name: /refresh/i });
    await expect(refreshButton).toBeVisible();

    // Start the long-running task
    const startButton = page.getByRole('button', { name: /start/i });
    await startButton.click();

    // Wait for task to be visible
    await page.waitForTimeout(500);

    // Verify task is still listed after refresh
    await page.reload();
    await expect(taskList).toBeVisible();
    await expect(taskItem).toBeVisible();

    // Verify task details are still visible
    await expect(taskName).toBeVisible();

    // Verify progress bar is still visible
    await expect(progressBar).toBeVisible();

    // Verify task status is still visible
    await expect(taskStatus).toBeVisible();

    // Verify refresh button is still visible
    await expect(refreshButton).toBeVisible();

    // Verify task is still in progress after refresh
    await expect(taskStatus).toContainText(/in progress/i);
  });

